targets.query:
// group() collapses the per-night_date tag groups into one table —
// without it Grafana renders one table per night. The float() cast is needed
// because duration_min is an integer and pivot refuses mixed value types.
from(bucket: v.defaultBucket)
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "pap_session")
  |> filter(fn: (r) => r.user == "${user}")
  |> filter(fn: (r) => r._field == "ahi" or r._field == "duration_min" or r._field == "avg_pressure" or r._field == "p90_pressure" or r._field == "avg_leak")
  |> map(fn: (r) => ({ r with _value: float(v: r._value) }))
  |> group()
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> keep(columns: ["_time", "duration_min", "ahi", "avg_pressure", "p90_pressure", "avg_leak"])
  |> sort(columns: ["_time"], desc: true)
